def compute(vars):
    margin_ratio = vars["v1"]
    margin_percentage = margin_ratio * 100

    return {
        "value": margin_percentage,
        "trace": {
            "margin_ratio": margin_ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
